css:
.pm-sim-container {
    padding: 24px;
    background: #0f172a;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e2e8f0;
}

.pm-sim-header {
    background: linear-gradient(135deg, #1e293b 0%, #334155 100%);
    border-left: 6px solid #3b82f6;
    padding: 24px 28px;
    margin-bottom: 24px;
    border-radius: 4px;
}

.pm-sim-header-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
}

.pm-sim-container .pm-sim-header h1 {
    color: #f1f5f9;
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    margin: 0;
    text-transform: uppercase;
}

.pm-sim-period-counter {
    background: #0f172a;
    border: 1px solid #475569;
    padding: 8px 16px;
    border-radius: 4px;
    font-size: 0.9rem;
    font-weight: 700;
    color: #3b82f6;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.pm-sim-subtitle {
    color: #94a3b8;
    font-size: 0.85rem;
    margin-top: 8px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.pm-sim-briefing {
    background: #1e293b;
    border: 1px solid #334155;
    border-top: 3px solid #f59e0b;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 24px;
}

.pm-sim-briefing-label {
    color: #f59e0b;
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 8px;
}

.pm-sim-briefing-title {
    color: #f1f5f9;
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 12px;
}

.pm-sim-briefing-text {
    color: #cbd5e1;
    font-size: 0.95rem;
    line-height: 1.6;
}

.pm-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}

.pm-sim-kpi-card {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 4px;
    padding: 16px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease;
}

.pm-sim-kpi-card:hover {
    border-color: #475569;
}

.pm-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, #3b82f6, #60a5fa);
}

.pm-sim-kpi-label {
    color: #94a3b8;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    margin-bottom: 8px;
}

.pm-sim-kpi-value {
    font-size: 1.75rem;
    font-weight: 700;
    color: #f1f5f9;
    line-height: 1;
    margin-bottom: 6px;
}

.pm-sim-kpi-sub {
    color: #64748b;
    font-size: 0.72rem;
    letter-spacing: 0.04em;
}

.pm-sim-controls {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
}

.pm-sim-container .pm-sim-controls h3 {
    color: #f1f5f9;
    font-size: 0.95rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-weight: 700;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #334155;
}

.pm-sim-decision-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 16px;
}

.pm-sim-decision {
    background: #0f172a;
    border: 1px solid #334155;
    border-radius: 4px;
    padding: 14px;
}

.pm-sim-decision-wide {
    grid-column: 1 / -1;
}

.pm-sim-decision label {
    display: block;
    color: #94a3b8;
    font-size: 0.7rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-weight: 600;
    margin-bottom: 8px;
}

.pm-sim-controls input[type="number"],
.pm-sim-controls select {
    background: #1e293b;
    border: 1px solid #475569;
    color: #f1f5f9;
    border-radius: 4px;
    padding: 8px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-weight: 600;
}

.pm-sim-controls select option {
    background: #1e293b;
    color: #f1f5f9;
}

.pm-sim-controls input:focus,
.pm-sim-controls select:focus {
    outline: none;
    border-color: #3b82f6;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.pm-sim-hint {
    color: #64748b;
    font-size: 0.72rem;
    margin-top: 6px;
    font-style: italic;
}

.pm-sim-button-row {
    display: flex;
    gap: 12px;
    margin-top: 20px;
    padding-top: 20px;
    border-top: 1px solid #334155;
    flex-wrap: wrap;
}

.pm-sim-container .pm-sim-btn-primary {
    background: linear-gradient(135deg, #3b82f6, #2563eb);
    border: none;
    color: #ffffff;
    padding: 10px 28px;
    font-size: 0.9rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    border-radius: 4px;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.pm-sim-container .pm-sim-btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(59, 130, 246, 0.4);
    color: #ffffff;
}

.pm-sim-container .pm-sim-btn-secondary {
    background: transparent;
    border: 1px solid #475569;
    color: #cbd5e1;
    padding: 10px 20px;
    font-size: 0.8rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    border-radius: 4px;
}

.pm-sim-container .pm-sim-btn-secondary:hover {
    background: #334155;
    color: #f1f5f9;
}

.pm-sim-history {
    background: #1e293b;
    border: 1px solid #334155;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 24px;
    overflow-x: auto;
}

.pm-sim-container .pm-sim-history h3 {
    color: #f1f5f9;
    font-size: 0.9rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-weight: 700;
    margin: 0 0 16px 0;
}

.pm-sim-history table {
    color: #e2e8f0;
    font-size: 0.85rem;
    width: 100%;
    background: transparent;
    margin: 0;
}

.pm-sim-history table th {
    color: #94a3b8;
    font-size: 0.7rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-bottom: 1px solid #475569 !important;
    border-top: none !important;
    background: #0f172a !important;
    padding: 10px 12px !important;
    font-weight: 700;
}

.pm-sim-history table td {
    border-top: 1px solid #334155 !important;
    background: transparent !important;
    color: #cbd5e1 !important;
    padding: 10px 12px !important;
}

.pm-sim-history table tbody tr:nth-of-type(odd) td {
    background: rgba(51, 65, 85, 0.3) !important;
}

.pm-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.pm-sim-chart-card {
    background: #1e293b;
    border: 1px solid #334155;
    border-top: 3px solid #10b981;
    border-radius: 4px;
    padding: 20px;
    height: 340px;
}

.pm-sim-chart-card canvas {
    max-height: 290px;
}

@media (max-width: 768px) {
    .pm-sim-container { padding: 12px; }
    .pm-sim-header { padding: 16px 18px; }
    .pm-sim-header-bar { flex-direction: column; align-items: flex-start; }
    .pm-sim-container .pm-sim-header h1 { font-size: 1.1rem; }
    .pm-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .pm-sim-kpi-value { font-size: 1.4rem; }
    .pm-sim-decision-row { grid-template-columns: 1fr; }
    .pm-sim-charts { grid-template-columns: 1fr; }
    .pm-sim-chart-card { height: 280px; }
}

