(function() {
    'use strict';

    const ROUNDS = [
        {
            title_en: `Phase 1: Planning & Approach Selection`,
            title_es: `Fase 1: Planeación y Selección de Enfoque`,
            desc_en: `Month 0. The board has approved a $12M budget plus $2M contingency to replace the legacy ERP at Manufactura Atlas (4 plants, 2,100 employees). You have 24 months. Select your methodology — Hybrid tends to fit a Cynefin-complicated manufacturing context best. Your methodology choice is locked after this phase.`,
            desc_es: `Mes 0. La junta aprobó $12M más $2M de contingencia para reemplazar el ERP legado de Manufactura Atlas (4 plantas, 2.100 empleados). Tiene 24 meses. Seleccione metodología — Híbrido suele ajustar mejor a un contexto complicado tipo Cynefin. La metodología queda bloqueada tras esta fase.`
        },
        {
            title_en: `Phase 2: Detailed Planning & Risk`,
            title_es: `Fase 2: Planeación Detallada y Riesgo`,
            desc_en: `Month 5. Economic headwinds are emerging — the board is whispering about budget cuts. Data migration scope is larger than expected and the integrator is pressing for more resources. Calibrate scope discipline, staffing, and change management investment to lock a realistic baseline.`,
            desc_es: `Mes 5. Vienen vientos económicos adversos — la junta susurra sobre recortes. La migración de datos es mayor de lo esperado y el integrador pide más recursos. Calibre disciplina de alcance, personal e inversión en gestión del cambio para fijar una línea base realista.`
        },
        {
            title_en: `Phase 3: Execution & Scope Pressure`,
            title_es: `Fase 3: Ejecución y Presión de Alcance`,
            desc_en: `Month 10. Business users filed change requests totaling +10% scope. Your senior integrator consultant was pulled to another client. Data migration is showing 15-20% data quality defects. Plant managers are skeptical; training attendance is low. How disciplined will you be?`,
            desc_es: `Mes 10. Los usuarios presentaron solicitudes de cambio por +10% del alcance. Su consultor senior fue reasignado. La migración de datos muestra 15-20% de defectos de calidad. Los gerentes de planta son escépticos; la asistencia a capacitación es baja. ¿Qué tan disciplinado será?`
        },
        {
            title_en: `Phase 4: Pressure & Difficult Trade-offs`,
            title_es: `Fase 4: Presión y Decisiones Difíciles`,
            desc_en: `Month 16. The executive team is pushing hard for the original 24-month go-live despite evidence of slippage. Budget is tracking to $14.2M. The PM is being recruited away. Operations and Finance are in conflict over inventory valuation. More scope creep is pending. Hold the line or bend?`,
            desc_es: `Mes 16. El equipo ejecutivo presiona por el go-live original de 24 meses a pesar de evidencia de retrasos. El presupuesto apunta a $14.2M. Reclutan al PM afuera. Operaciones y Finanzas en conflicto por la valoración de inventarios. Más scope creep pendiente. ¿Mantiene la línea o cede?`
        },
        {
            title_en: `Phase 5: Go-Live Decision`,
            title_es: `Fase 5: Decisión de Go-Live`,
            desc_en: `Month 22. Decision time. Readiness is mixed: system testing shows residual defects, data migration is stable, users have partial training, and organizational resistance persists in some plants. Choose your go-live path — each option carries a different risk-return profile.`,
            desc_es: `Mes 22. Momento de decidir. La preparación es mixta: las pruebas muestran defectos residuales, la migración está estable, los usuarios tienen capacitación parcial y persiste resistencia en algunas plantas. Elija su ruta de go-live — cada opción tiene un perfil riesgo-retorno distinto.`
        }
    ];

    class ProjectArenaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'ProjectArena ERP Implementation';
            this.version = '1.1.0';
            this.ROUNDS = ROUNDS;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budgetTotal: 14.0,
                    budgetUsed: 0,
                    plannedValue: 0,
                    earnedValue: 0,
                    actualCost: 0,
                    monthsElapsed: 0,
                    monthsTarget: 24,
                    spi: 1.00,
                    cpi: 1.00,
                    scopeSize: 100,
                    stakeholderBuyIn: 70,
                    qualityIndex: 80,
                    riskExposure: 50,
                    approach: null,
                    goLivePath: null,
                    finalAdoption: 0,
                    spiHistory: [],
                    cpiHistory: [],
                    scopeHistory: [],
                    stakeholderHistory: [],
                    qualityHistory: [],
                    plannedValueHistory: [],
                    earnedValueHistory: [],
                    actualCostHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    approach: 'hybrid',
                    scopeDiscipline: 5,
                    cmInvestment: 300,
                    staffing: 80,
                    goLive: 'reduced'
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 50);
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : 'en';
            var title = (lang === 'es') ? round.title_es : round.title_en;
            var desc = (lang === 'es') ? round.desc_es : round.desc_en;

            var briefTitleEl = document.getElementById('briefingTitle');
            if (briefTitleEl) briefTitleEl.innerHTML = title;
            var briefTextEl = document.getElementById('briefingText');
            if (briefTextEl) briefTextEl.innerHTML = desc;

            var approachEl = document.getElementById('approachSelect');
            if (approachEl) {
                var locked = (period > 1);
                approachEl.disabled = locked;
                if (locked && state.domainState && state.domainState.approach) {
                    approachEl.value = state.domainState.approach;
                }
            }

            var goLivePanel = document.getElementById('goLivePanel');
            if (goLivePanel) {
                goLivePanel.style.display = (period === 5) ? 'block' : 'none';
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var approachEl = document.getElementById('approachSelect');
            if (approachEl) decisions.approach = approachEl.value;

            var scopeEl = document.getElementById('scopeDisciplineInput');
            if (scopeEl) decisions.scopeDiscipline = parseFloat(scopeEl.value);

            var cmEl = document.getElementById('cmInvestmentInput');
            if (cmEl) decisions.cmInvestment = parseFloat(cmEl.value);

            var staffEl = document.getElementById('staffingInput');
            if (staffEl) decisions.staffing = parseFloat(staffEl.value);

            var goLiveEl = document.getElementById('goLiveSelect');
            if (goLiveEl) decisions.goLive = goLiveEl.value;

            if (isNaN(decisions.scopeDiscipline) || decisions.scopeDiscipline < 1 || decisions.scopeDiscipline > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('scope_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.cmInvestment) || decisions.cmInvestment < 50 || decisions.cmInvestment > 1000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('cm_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.staffing) || decisions.staffing < 30 || decisions.staffing > 200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('staffing_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            if (period === 1) {
                ds.approach = d.approach;
            }
            var approach = ds.approach || 'hybrid';

            var monthsAdvanced = 4.8;

            var approachFit = 1.0;
            if (approach === 'hybrid') approachFit = 1.05;
            else if (approach === 'waterfall') approachFit = 0.97;
            else if (approach === 'agile') approachFit = 0.92;

            var disc = d.scopeDiscipline;
            var scopeCreepPct = 0;
            var basePressure = [0, 4, 9, 7, 0][period - 1];
            if (basePressure > 0) {
                scopeCreepPct = Math.max(0, basePressure * (11 - disc) / 10);
            }
            ds.scopeSize += scopeCreepPct;

            var cmEffect = Math.min(1.2, 0.55 + (d.cmInvestment / 650));

            var idealStaff = 90;
            var staffRatio = d.staffing / idealStaff;
            var productivityFactor = Math.max(0.55, 1 - Math.abs(staffRatio - 1) * 0.4);

            var baseBurnPerMonth = 0.40 + (d.staffing / 200) * 0.55;
            var phaseCostMultiplier = [0.7, 0.9, 1.1, 1.2, 1.0][period - 1];
            var periodCost = baseBurnPerMonth * monthsAdvanced * phaseCostMultiplier;
            periodCost += scopeCreepPct * 0.035;
            periodCost += d.cmInvestment / 1000;

            var plannedProgress = 100 / 5;
            var plannedValueAdd = ds.budgetTotal * plannedProgress / 100;

            var earnedProgress = plannedProgress * approachFit * productivityFactor * cmEffect;
            if (period === 3) earnedProgress *= 0.90;
            if (period === 4) earnedProgress *= (0.88 + disc * 0.015);
            var earnedValueAdd = ds.budgetTotal * earnedProgress / 100;

            ds.plannedValue += plannedValueAdd;
            ds.earnedValue += earnedValueAdd;
            ds.actualCost += periodCost;
            ds.budgetUsed = ds.actualCost;

            ds.spi = (ds.plannedValue > 0) ? ds.earnedValue / ds.plannedValue : 1.0;
            ds.cpi = (ds.actualCost > 0) ? ds.earnedValue / ds.actualCost : 1.0;
            ds.spi = Math.round(ds.spi * 100) / 100;
            ds.cpi = Math.round(ds.cpi * 100) / 100;

            var cmDelta = (d.cmInvestment - 300) * 0.018;
            var discDelta = (disc - 5) * 0.7;
            var buyInDelta = cmDelta + discDelta;
            if (period === 2) buyInDelta -= 3;
            if (period === 3) buyInDelta -= 6;
            if (period === 4) buyInDelta -= 5;
            ds.stakeholderBuyIn = Math.max(0, Math.min(100, ds.stakeholderBuyIn + buyInDelta));

            var qualityDelta = 0;
            qualityDelta += (productivityFactor - 0.8) * 10;
            qualityDelta += (disc - 5) * 0.8;
            if (scopeCreepPct > 5) qualityDelta -= 3;
            if (period === 3) qualityDelta -= 2;
            if (period === 4) qualityDelta -= 3;
            ds.qualityIndex = Math.max(0, Math.min(100, ds.qualityIndex + qualityDelta));

            var riskDelta = 0;
            riskDelta += (5 - disc) * 1.2;
            riskDelta -= (cmEffect - 0.9) * 15;
            if (scopeCreepPct > 5) riskDelta += 4;
            if (approach === 'agile') riskDelta += 2;
            if (approach === 'waterfall' && scopeCreepPct > 5) riskDelta += 3;
            ds.riskExposure = Math.max(0, Math.min(100, ds.riskExposure + riskDelta));

            ds.monthsElapsed += monthsAdvanced;

            var adoption = null;
            if (period === 5) {
                ds.goLivePath = d.goLive;
                var pathEffects = {
                    full:     { adoption: 0.85, quality: 0.88, cost: 1.00, schedule: 1.00 },
                    reduced:  { adoption: 0.98, quality: 1.02, cost: 1.03, schedule: 1.02 },
                    parallel: { adoption: 1.08, quality: 1.08, cost: 1.12, schedule: 1.05 },
                    delay:    { adoption: 1.02, quality: 1.10, cost: 1.08, schedule: 1.15 }
                };
                var eff = pathEffects[d.goLive] || pathEffects.reduced;
                adoption = Math.round(ds.stakeholderBuyIn * eff.adoption * (ds.qualityIndex / 90));
                adoption = Math.max(0, Math.min(100, adoption));
                ds.finalAdoption = adoption;
                ds.actualCost = ds.actualCost * eff.cost;
                ds.budgetUsed = ds.actualCost;
                ds.monthsElapsed = ds.monthsElapsed * eff.schedule;
                ds.qualityIndex = Math.max(0, Math.min(100, ds.qualityIndex * eff.quality));
            }

            ds.spiHistory.push(ds.spi);
            ds.cpiHistory.push(ds.cpi);
            ds.scopeHistory.push(Math.round(ds.scopeSize));
            ds.stakeholderHistory.push(Math.round(ds.stakeholderBuyIn));
            ds.qualityHistory.push(Math.round(ds.qualityIndex));
            ds.plannedValueHistory.push(Math.round(ds.plannedValue * 100) / 100);
            ds.earnedValueHistory.push(Math.round(ds.earnedValue * 100) / 100);
            ds.actualCostHistory.push(Math.round(ds.actualCost * 100) / 100);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({
                    currentPeriod: period + 1,
                    domainState: ds
                });
            }, 400);

            return {
                period: period,
                approach: approach,
                scopeDiscipline: d.scopeDiscipline,
                cmInvestment: d.cmInvestment,
                staffing: d.staffing,
                goLive: (period === 5) ? d.goLive : null,
                periodCost: Math.round(periodCost * 100) / 100,
                budgetUsed: Math.round(ds.budgetUsed * 100) / 100,
                monthsElapsed: Math.round(ds.monthsElapsed * 10) / 10,
                spi: ds.spi,
                cpi: ds.cpi,
                scopeSize: Math.round(ds.scopeSize),
                stakeholderBuyIn: Math.round(ds.stakeholderBuyIn),
                qualityIndex: Math.round(ds.qualityIndex),
                riskExposure: Math.round(ds.riskExposure),
                adoption: adoption
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetUsedDisplay', 'domainState.budgetUsed',
                (v) => '$' + (Math.round(v * 100) / 100).toFixed(2) + 'M');
            uiManager.bind('budgetTotalDisplay', 'domainState.budgetTotal',
                (v) => '$' + v.toFixed(1) + 'M');
            uiManager.bind('monthsDisplay', 'domainState.monthsElapsed',
                (v) => (Math.round(v * 10) / 10).toString());
            uiManager.bind('spiDisplay', 'domainState.spi',
                (v) => Number(v).toFixed(2));
            uiManager.bind('cpiDisplay', 'domainState.cpi',
                (v) => Number(v).toFixed(2));
            uiManager.bind('scopeDisplay', 'domainState.scopeSize',
                (v) => Math.round(v) + '%');
            uiManager.bind('stakeholderDisplay', 'domainState.stakeholderBuyIn',
                (v) => Math.round(v).toString());
            uiManager.bind('qualityDisplay', 'domainState.qualityIndex',
                (v) => Math.round(v).toString());
            uiManager.bind('riskDisplay', 'domainState.riskExposure',
                (v) => Math.round(v).toString());
        }

        getChartConfig() {
            return {
                evmChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Planned Value ($M)',
                                data: [],
                                borderColor: '#94a3b8',
                                backgroundColor: 'rgba(148,163,184,0.1)',
                                borderWidth: 2,
                                borderDash: [6, 4],
                                fill: false,
                                tension: 0.1
                            },
                            {
                                label: 'Earned Value ($M)',
                                data: [],
                                borderColor: '#10b981',
                                backgroundColor: 'rgba(16,185,129,0.15)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Actual Cost ($M)',
                                data: [],
                                borderColor: '#ef4444',
                                backgroundColor: 'rgba(239,68,68,0.15)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
